#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/irq_offload.h>

/* Define stack size for test threads. */
#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

/* Define thread priority for test threads. */
#define THREAD_PRIORITY K_PRIO_PREEMPT(10)

/* Global k_event object used across test cases. */
static struct k_event test_event;

/* Thread stack and data for helper threads. */
static K_THREAD_STACK_DEFINE(tstack, STACK_SIZE);
static struct k_thread tdata;

/*
 * Event masks used in various test cases.
 * These define individual bits that can be set or waited for.
 */
#define EVENT_BIT_0  BIT(0)
#define EVENT_BIT_1  BIT(1)
#define EVENT_BIT_2  BIT(2)
#define EVENT_BIT_3  BIT(3)
#define EVENT_BIT_4  BIT(4)
#define EVENT_BIT_5  BIT(5)
#define EVENT_BIT_6  BIT(6)
#define EVENT_BIT_7  BIT(7)
#define EVENT_BIT_8  BIT(8)
#define EVENT_BIT_9  BIT(9)
#define EVENT_BIT_10 BIT(10)
#define EVENT_BIT_11 BIT(11)
#define EVENT_BIT_12 BIT(12)
#define EVENT_BIT_13 BIT(13)
#define EVENT_BIT_14 BIT(14)
#define EVENT_BIT_15 BIT(15)
#define EVENT_BIT_16 BIT(16)
#define EVENT_BIT_17 BIT(17)
#define EVENT_BIT_18 BIT(18)
#define EVENT_BIT_19 BIT(19)
#define EVENT_BIT_20 BIT(20)
#define EVENT_BIT_21 BIT(21)
#define EVENT_BIT_22 BIT(22)
#define EVENT_BIT_23 BIT(23)
#define EVENT_BIT_24 BIT(24)
#define EVENT_BIT_25 BIT(25)
#define EVENT_BIT_26 BIT(26)
#define EVENT_BIT_27 BIT(27)
#define EVENT_BIT_28 BIT(28)
#define EVENT_BIT_29 BIT(29)
#define EVENT_BIT_30 BIT(30)
#define EVENT_BIT_31 BIT(31)

/* A mask representing all possible events (32 bits). */
#define ALL_EVENTS_MASK 0xFFFFFFFF

/*
 * Specific event combinations used for testing.
 * These are chosen to be distinct and cover various scenarios.
 */
#define TEST_EVENTS_A (EVENT_BIT_0 | EVENT_BIT_2 | EVENT_BIT_4)
#define TEST_EVENTS_B (EVENT_BIT_1 | EVENT_BIT_3 | EVENT_BIT_5)
#define TEST_EVENTS_C (EVENT_BIT_6 | EVENT_BIT_7)
#define TEST_EVENTS_D (EVENT_BIT_8 | EVENT_BIT_9 | EVENT_BIT_10)
#define TEST_EVENTS_E (EVENT_BIT_11 | EVENT_BIT_12)
#define TEST_EVENTS_F (EVENT_BIT_13 | EVENT_BIT_14 | EVENT_BIT_15)
#define TEST_EVENTS_G (EVENT_BIT_16 | EVENT_BIT_17)
#define TEST_EVENTS_H (EVENT_BIT_18 | EVENT_BIT_19 | EVENT_BIT_20)
#define TEST_EVENTS_I (EVENT_BIT_21 | EVENT_BIT_22)
#define TEST_EVENTS_J (EVENT_BIT_23 | EVENT_BIT_24 | EVENT_BIT_25)
#define TEST_EVENTS_K (EVENT_BIT_26 | EVENT_BIT_27)
#define TEST_EVENTS_L (EVENT_BIT_28 | EVENT_BIT_29 | EVENT_BIT_30)
#define TEST_EVENTS_M (EVENT_BIT_31)


/*
 * @brief Helper thread function for waiting on events without resetting them.
 *
 * This thread waits for a specified set of events on a given k_event object.
 * It can wait for all events or any event, and does not reset the events
 * in the k_event object upon successful reception.
 *
 * @param p1 Pointer to the k_event object.
 * @param p2 Event mask to wait for.
 * @param p3 Boolean flag: true for k_event_wait_all, false for k_event_wait_any.
 */
static void event_waiter_thread(void *p1, void *p2, void *p3)
{
    struct k_event *event = (struct k_event *)p1;
    uint32_t events_to_wait = (uint32_t)(uintptr_t)p2;
    bool all = (bool)(uintptr_t)p3;
    uint32_t received_events;

    if (all) {
        received_events = k_event_wait_all(event, events_to_wait, false, K_FOREVER);
    } else {
        received_events = k_event_wait_any(event, events_to_wait, false, K_FOREVER);
    }

    zassert_equal(received_events, events_to_wait,
                  "Received events mismatch in non-resetting waiter thread. Expected 0x%x, got 0x%x",
                  events_to_wait, received_events);
}

/*
 * @brief Helper thread function for waiting on events and resetting them.
 *
 * This thread waits for a specified set of events on a given k_event object.
 * It can wait for all events or any event, and *resets* the events
 * in the k_event object upon successful reception.
 *
 * @param p1 Pointer to the k_event object.
 * @param p2 Event mask to wait for.
 * @param p3 Boolean flag: true for k_event_wait_all, false for k_event_wait_any.
 */
static void event_waiter_reset_thread(void *p1, void *p2, void *p3)
{
    struct k_event *event = (struct k_event *)p1;
    uint32_t events_to_wait = (uint32_t)(uintptr_t)p2;
    bool all = (bool)(uintptr_t)p3;
    uint32_t received_events;

    if (all) {
        received_events = k_event_wait_all(event, events_to_wait, true, K_FOREVER);
    } else {
        received_events = k_event_wait_any(event, events_to_wait, true, K_FOREVER);
    }

    zassert_equal(received_events, events_to_wait,
                  "Received events mismatch in resetting waiter thread. Expected 0x%x, got 0x%x",
                  events_to_wait, received_events);
}

/*
 * @brief Test k_event_post functionality.
 *
 * @details This test verifies that k_event_post correctly sets the specified
 *          event bits in the k_event object. It also checks for setting
 *          multiple events and subsequent clearing.
 */
ZTEST(events_api, test_event_post)
{
    k_event_init(&test_event);
    zassert_equal(test_event.events, 0, "Event object not initialized to 0");

    k_event_set(&test_event, TEST_EVENTS_A);
    zassert_equal(test_event.events, TEST_EVENTS_A, "Single event mask not set correctly");

    k_event_set(&test_event, TEST_EVENTS_B | TEST_EVENTS_C);
    zassert_equal(test_event.events, TEST_EVENTS_A | TEST_EVENTS_B | TEST_EVENTS_C,
                  "Multiple event masks not accumulated correctly");

    k_event_clear(&test_event, ALL_EVENTS_MASK);
    zassert_equal(test_event.events, 0, "Event object not cleared correctly after post test");
}

/*
 * @brief Test k_event_receive_existing functionality.
 *
 * @details This test verifies that k_event_wait_any and k_event_wait_all
 *          can immediately receive already set events when K_NO_WAIT is used,
 *          and that the event state is not altered if reset is false.
 */
ZTEST(events_api, test_event_receive_existing)
{
    k_event_init(&test_event);
    k_event_set(&test_event, TEST_EVENTS_A | TEST_EVENTS_B | TEST_EVENTS_C);

    uint32_t received = k_event_wait_any(&test_event, TEST_EVENTS_A, false, K_NO_WAIT);
    zassert_equal(received, TEST_EVENTS_A, "Did not receive existing event (any, no_wait)");
    zassert_equal(test_event.events, TEST_EVENTS_A | TEST_EVENTS_B | TEST_EVENTS_C,
                  "Event state changed unexpectedly after any wait (no_wait)");

    received = k_event_wait_all(&test_event, TEST_EVENTS_A | TEST_EVENTS_B, false, K_NO_WAIT);
    zassert_equal(received, TEST_EVENTS_A | TEST_EVENTS_B, "Did not receive all existing events (all, no_wait)");
    zassert_equal(test_event.events, TEST_EVENTS_A | TEST_EVENTS_B | TEST_EVENTS_C,
                  "Event state changed unexpectedly after all wait (no_wait)");

    k_event_clear(&test_event, ALL_EVENTS_MASK);
    zassert_equal(test_event.events, 0, "Event object not cleared correctly after receive existing test");
}

/*
 * @brief Test k_event_wait_any with timeout and no events present.
 *
 * @details Verifies that k_event_wait_any returns 0 (timeout) when no matching
 *          events are present and a timeout occurs.
 */
ZTEST(events_api, test_event_wait_any_timeout_no_events)
{
    k_event_init(&test_event);
    uint32_t received = k_event_wait_any(&test_event, TEST_EVENTS_A, false, K_MSEC(10));
    zassert_equal(received, 0, "Received events unexpectedly with timeout (any, no events)");
    zassert_equal(test_event.events, 0, "Event state changed unexpectedly after timeout (any, no events)");
}

/*
 * @brief Test k_event_wait_all with timeout and no events present.
 *
 * @details Verifies that k_event_wait_all returns 0 (timeout) when no matching
 *          events are present and a timeout occurs.
 */
ZTEST(events_api, test_event_wait_all_timeout_no_events)
{
    k_event_init(&test_event);
    uint32_t received = k_event_wait_all(&test_event, TEST_EVENTS_A | TEST_EVENTS_B, false, K_MSEC(10));
    zassert_equal(received, 0, "Received events unexpectedly with timeout (all, no events)");
    zassert_equal(test_event.events, 0, "Event state changed unexpectedly after timeout (all, no events)");
}

/*
 * @brief Test k_event_wait_all with timeout and partial events present.
 *
 * @details Verifies that k_event_wait_all returns 0 (timeout) when only a
 *          subset of the required events are present and a timeout occurs.
 */
ZTEST(events_api, test_event_wait_all_timeout_partial_events)
{
    k_event_init(&test_event);
    k_event_set(&test_event, TEST_EVENTS_A);
    uint32_t received = k_event_wait_all(&test_event, TEST_EVENTS_A | TEST_EVENTS_B, false, K_MSEC(10));
    zassert_equal(received, 0, "Received events unexpectedly with partial timeout (all)");
    zassert_equal(test_event.events, TEST_EVENTS_A, "Event state changed unexpectedly after partial timeout (all)");
    k_event_clear(&test_event, ALL_EVENTS_MASK);
}

/*
 * @brief Test k_event_wait_any with multiple threads.
 *
 * @details A helper thread waits for an event, and the main thread posts it.
 *          Verifies that the waiting thread is unblocked correctly.
 */
ZTEST(events_api, test_event_wait_any_multi_thread)
{
    k_event_init(&test_event);
    k_thread_create(&tdata, tstack, STACK_SIZE,
                    event_waiter_thread, &test_event, (void *)(uintptr_t)TEST_EVENTS_A, (void *)false,
                    THREAD_PRIORITY, 0, K_NO_WAIT);

    k_sleep(K_MSEC(10)); /* Give time for the helper thread to start waiting */
    k_event_set(&test_event, TEST_EVENTS_A);
    k_thread_join(&tdata, K_FOREVER);
    zassert_equal(test_event.events, TEST_EVENTS_A, "Event state changed unexpectedly after any multi-thread wait");
    k_event_clear(&test_event, ALL_EVENTS_MASK);
}

/*
 * @brief Test k_event_wait_all with multiple threads.
 *
 * @details A helper thread waits for multiple events, and the main thread
 *          posts them one by one. Verifies that the waiting thread is unblocked
 *          only when all required events are present.
 */
ZTEST(events_api, test_event_wait_all_multi_thread)
{
    k_event_init(&test_event);
    k_thread_create(&tdata, tstack, STACK_SIZE,
                    event_waiter_thread, &test_event, (void *)(uintptr_t)(TEST_EVENTS_A | TEST_EVENTS_B), (void *)true,
                    THREAD_PRIORITY, 0, K_NO_WAIT);

    k_sleep(K_MSEC(10)); /* Give time for the helper thread to start waiting */
    k_event_set(&test_event, TEST_EVENTS_A);
    k_sleep(K_MSEC(10)); /* Helper thread should still be waiting for TEST_EVENTS_B */
    zassert_equal(test_event.events, TEST_EVENTS_A, "Event state changed unexpectedly during all multi-thread wait");

    k_event_set(&test_event, TEST_EVENTS_B);
    k_thread_join(&tdata, K_FOREVER);
    zassert_equal(test_event.events, TEST_EVENTS_A | TEST_EVENTS_B, "Event state changed unexpectedly after all multi-thread wait");
    k_event_clear(&test_event, ALL_EVENTS_MASK);
}

/*
 * @brief Test k_event_reset_on_wait functionality.
 *
 * @details This test verifies that when the 'reset' parameter is true in
 *          k_event_wait_any or k_event_wait_all, the events that were
 *          successfully waited for are cleared from the k_event object.
 */
ZTEST(events_api, test_event_reset_on_wait)
{
    k_event_init(&test_event);
    k_event_set(&test_event, 0x123); /* Set a specific event mask for testing */

    k_thread_create(&tdata, tstack, STACK_SIZE,
                    event_waiter_reset_thread, &test_event, (void *)(uintptr_t)0x123, (void *)true,
                    THREAD_PRIORITY, 0, K_NO_WAIT);

    k_sleep(K_MSEC(10)); /* Give time for the helper thread to start waiting */

    /*
     * The event_waiter_reset_thread will wait for 0x123 with reset=true.
     * It will then receive 0x123 and clear it from the event object.
     * So, after the thread completes, test_event.events should be 0.
     */

    k_thread_join(&tdata, K_FOREVER);

    /*
     * This is the assertion that was failing in the original code.
     * It incorrectly expected the events to remain 0x123, but with reset=true,
     * they should have been cleared to 0.
     */
    zassert_equal(test_event.events, 0, "Events should be cleared after reset wait, but are 0x%x", test_event.events);

    k_event_clear(&test_event, ALL_EVENTS_MASK); /* Ensure clean state for next test */
}

/*
 * @brief Test k_event_clear functionality.
 *
 * @details This test verifies that k_event_clear correctly clears specified
 *          event bits from the k_event object, both for single and multiple bits.
 */
ZTEST(events_api, test_event_clear)
{
    k_event_init(&test_event);
    k_event_set(&test_event, TEST_EVENTS_A | TEST_EVENTS_B | TEST_EVENTS_C | TEST_EVENTS_D);
    zassert_equal(test_event.events, TEST_EVENTS_A | TEST_EVENTS_B | TEST_EVENTS_C | TEST_EVENTS_D,
                  "Initial set failed for clear test");

    k_event_clear(&test_event, TEST_EVENTS_B);
    zassert_equal(test_event.events, TEST_EVENTS_A | TEST_EVENTS_C | TEST_EVENTS_D,
                  "Clear single event failed");

    k_event_clear(&test_event, TEST_EVENTS_A | TEST_EVENTS_D);
    zassert_equal(test_event.events, TEST_EVENTS_C, "Clear multiple events failed");

    k_event_clear(&test_event, TEST_EVENTS_C);
    zassert_equal(test_event.events, 0, "Clear last event failed");
}

/*
 * @brief Test k_event_set from ISR context.
 *
 * @details Verifies that k_event_set can be called from an ISR and correctly
 *          sets event bits.
 */
ZTEST(events_api, test_event_set_isr)
{
    k_event_init(&test_event);
    irq_offload_start_code(
        (irq_offload_routine_t) {
            k_event_set(&test_event, TEST_EVENTS_E);
        }, NULL);
    zassert_equal(test_event.events, TEST_EVENTS_E, "ISR set event failed");
    k_event_clear(&test_event, ALL_EVENTS_MASK);
}

/*
 * @brief Test k_event_clear from ISR context.
 *
 * @details Verifies that k_event_clear can be called from an ISR and correctly
 *          clears event bits.
 */
ZTEST(events_api, test_event_clear_isr)
{
    k_event_init(&test_event);
    k_event_set(&test_event, TEST_EVENTS_E | TEST_EVENTS_F);
    irq_offload_start_code(
        (irq_offload_routine_t) {
            k_event_clear(&test_event, TEST_EVENTS_E);
        }, NULL);
    zassert_equal(test_event.events, TEST_EVENTS_F, "ISR clear event failed");
    k_event_clear(&test_event, ALL_EVENTS_MASK);
}

/*
 * @brief Test k_event_wait_any from ISR context with K_NO_WAIT.
 *
 * @details Verifies that k_event_wait_any can be called from an ISR with
 *          K_NO_WAIT and correctly retrieves existing events without blocking.
 */
ZTEST(events_api, test_event_wait_any_isr)
{
    k_event_init(&test_event);
    k_event_set(&test_event, TEST_EVENTS_E | TEST_EVENTS_G);

    uint32_t received = 0;
    irq_offload_start_code(
        (irq_offload_routine_t) {
            received = k_event_wait_any(&test_event, TEST_EVENTS_E | TEST_EVENTS_F, false, K_NO_WAIT);
        }, NULL);
    zassert_equal(received, TEST_EVENTS_E, "ISR wait_any failed to get existing event");
    zassert_equal(test_event.events, TEST_EVENTS_E | TEST_EVENTS_G, "Event state changed unexpectedly in ISR wait_any");

    k_event_clear(&test_event, ALL_EVENTS_MASK);
}

/*
 * @brief Test k_event_wait_all from ISR context with K_NO_WAIT.
 *
 * @details Verifies that k_event_wait_all can be called from an ISR with
 *          K_NO_WAIT and correctly retrieves existing events without blocking.
 */
ZTEST(events_api, test_event_wait_all_isr)
{
    k_event_init(&test_event);
    k_event_set(&test_event, TEST_EVENTS_E | TEST_EVENTS_F | TEST_EVENTS_G);

    uint32_t received = 0;
    irq_offload_start_code(
        (irq_offload_routine_t) {
            received = k_event_wait_all(&test_event, TEST_EVENTS_E | TEST_EVENTS_F, false, K_NO_WAIT);
        }, NULL);
    zassert_equal(received, TEST_EVENTS_E | TEST_EVENTS_F, "ISR wait_all failed to get existing events");
    zassert_equal(test_event.events, TEST_EVENTS_E | TEST_EVENTS_F | TEST_EVENTS_G, "Event state changed unexpectedly in ISR wait_all");

    k_event_clear(&test_event, ALL_EVENTS_MASK);
}

/*
 * @brief Test k_event_wait_any from ISR context with K_NO_WAIT and reset.
 *
 * @details Verifies that k_event_wait_any from ISR with K_NO_WAIT and reset=true
 *          correctly retrieves events and clears them from the object.
 */
ZTEST(events_api, test_event_wait_any_isr_reset)
{
    k_event_init(&test_event);
    k_event_set(&test_event, TEST_EVENTS_E | TEST_EVENTS_G);

    uint32_t received = 0;
    irq_offload_start_code(
        (irq_offload_routine_t) {
            received = k_event_wait_any(&test_event, TEST_EVENTS_E | TEST_EVENTS_F, true, K_NO_WAIT);
        }, NULL);
    zassert_equal(received, TEST_EVENTS_E, "ISR wait_any_reset failed to get existing event");
    zassert_equal(test_event.events, TEST_EVENTS_G, "Event state not reset correctly in ISR wait_any_reset");

    k_event_clear(&test_event, ALL_EVENTS_MASK);
}

/*
 * @brief Test k_event_wait_all from ISR context with K_NO_WAIT and reset.
 *
 * @details Verifies that k_event_wait_all from ISR with K_NO_WAIT and reset=true
 *          correctly retrieves events and clears them from the object.
 */
ZTEST(events_api, test_event_wait_all_isr_reset)
{
    k_event_init(&test_event);
    k_event_set(&test_event, TEST_EVENTS_E | TEST_EVENTS_F | TEST_EVENTS_G);

    uint32_t received = 0;
    irq_offload_start_code(
        (irq_offload_routine_t) {
            received = k_event_wait_all(&test_event, TEST_EVENTS_E | TEST_EVENTS_F, true, K_NO_WAIT);
        }, NULL);
    zassert_equal(received, TEST_EVENTS_E | TEST_EVENTS_F, "ISR wait_all_reset failed to get existing events");
    zassert_equal(test_event.events, TEST_EVENTS_G, "Event state not reset correctly in ISR wait_all_reset");

    k_event_clear(&test_event, ALL_EVENTS_MASK);
}

ZTEST_SUITE(events_api, NULL, NULL, NULL, NULL, NULL);
